package rw.umurava.healthtransport;

import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import rw.umurava.community.CommunityMembershipRepository;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;

@Service
public class HealthTransportService {
 private static final String ACTIVE="ACTIVE"; private final JdbcTemplate jdbc; private final CommunityMembershipRepository memberships;
 public HealthTransportService(JdbcTemplate jdbc,CommunityMembershipRepository memberships){this.jdbc=jdbc;this.memberships=memberships;}
 @Transactional(readOnly=true) public List<Map<String,Object>> facilities(UUID user,UUID community){member(user,community);return jdbc.queryForList("SELECT id,name,facility_type,service_status,beds_available,oxygen_available,updated_at FROM health_facilities WHERE community_id=? ORDER BY name",community);}
 @Transactional public Map<String,Object> addFacility(UUID user,UUID community,String name,String type){role(user,community,"HEALTH_WORKER");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO health_facilities(id,community_id,name,facility_type,updated_by) VALUES (?,?,?,?,?)",id,community,name.trim(),type.trim(),user);return jdbc.queryForMap("SELECT id,name,facility_type,service_status,beds_available,oxygen_available FROM health_facilities WHERE id=?",id);}
 @Transactional public Map<String,Object> updateFacility(UUID user,UUID community,UUID id,String status,int beds,boolean oxygen){role(user,community,"HEALTH_WORKER");if(!Set.of("OPEN","LIMITED","CLOSED","UNKNOWN").contains(status)||beds<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid facility status or bed count");int n=jdbc.update("UPDATE health_facilities SET service_status=?,beds_available=?,oxygen_available=?,updated_by=?,updated_at=NOW() WHERE id=? AND community_id=?",status,beds,oxygen,user,id,community);if(n==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Facility not found");return jdbc.queryForMap("SELECT id,name,facility_type,service_status,beds_available,oxygen_available,updated_at FROM health_facilities WHERE id=?",id);}
 @Transactional(readOnly=true) public List<Map<String,Object>> vehicles(UUID user,UUID community){member(user,community);return jdbc.queryForList("SELECT id,vehicle_code,vehicle_type,capacity,status,latitude,longitude,updated_at FROM transport_vehicles WHERE community_id=? ORDER BY vehicle_code",community);}
 @Transactional public Map<String,Object> addVehicle(UUID user,UUID community,String code,String type,int capacity,Double lat,Double lon){role(user,community,"TRANSPORT_COORDINATOR");if(capacity<=0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Vehicle capacity must be positive");UUID id=UUID.randomUUID();try{jdbc.update("INSERT INTO transport_vehicles(id,community_id,vehicle_code,vehicle_type,capacity,latitude,longitude) VALUES (?,?,?,?,?,?,?)",id,community,code.trim(),type.trim(),capacity,lat,lon);}catch(org.springframework.dao.DuplicateKeyException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"Vehicle code already exists in this community");}return jdbc.queryForMap("SELECT id,vehicle_code,vehicle_type,capacity,status,latitude,longitude FROM transport_vehicles WHERE id=?",id);}
 @Transactional(readOnly=true) public List<Map<String,Object>> requests(UUID user,UUID community){member(user,community);return jdbc.queryForList("SELECT id,request_type,priority,pickup_latitude,pickup_longitude,destination_latitude,destination_longitude,status,notes,assigned_vehicle_id,created_at,updated_at FROM transport_requests WHERE community_id=? ORDER BY CASE priority WHEN 'CRITICAL' THEN 0 WHEN 'HIGH' THEN 1 ELSE 2 END,created_at",community);}
 @Transactional public Map<String,Object> createRequest(UUID user,UUID community,String type,String priority,double pLat,double pLon,double dLat,double dLon,String notes){member(user,community);if(!Set.of("LOW","NORMAL","HIGH","CRITICAL").contains(priority))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid priority");if(notes!=null&&notes.length()>500)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Notes are too long; do not include patient names or medical identifiers");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO transport_requests(id,community_id,request_type,priority,pickup_latitude,pickup_longitude,destination_latitude,destination_longitude,notes,requested_by) VALUES (?,?,?,?,?,?,?,?,?,?)",id,community,type.trim(),priority,pLat,pLon,dLat,dLon,notes,user);return jdbc.queryForMap("SELECT id,request_type,priority,pickup_latitude,pickup_longitude,destination_latitude,destination_longitude,status,notes,created_at FROM transport_requests WHERE id=?",id);}
 @Transactional public Map<String,Object> updateRequest(UUID user,UUID community,UUID request,String status,UUID vehicle){role(user,community,"TRANSPORT_COORDINATOR");if(!Set.of("ACCEPTED","EN_ROUTE","COMPLETED","CANCELLED").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid transport request status");var rows=jdbc.query("SELECT status,assigned_vehicle_id FROM transport_requests WHERE id=? AND community_id=? FOR UPDATE",(rs,n)->new Object[]{rs.getString(1),rs.getObject(2,UUID.class)},request,community);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Transport request not found");String current=(String)rows.getFirst()[0];UUID previous=(UUID)rows.getFirst()[1];boolean allowed=(current.equals("NEW")&&(status.equals("ACCEPTED")||status.equals("CANCELLED")))||(current.equals("ACCEPTED")&&(status.equals("EN_ROUTE")||status.equals("CANCELLED")))||(current.equals("EN_ROUTE")&&status.equals("COMPLETED"));if(!allowed)throw new ResponseStatusException(HttpStatus.CONFLICT,"Invalid transport request state transition");UUID selected=vehicle==null?previous:vehicle;if(status.equals("ACCEPTED")||status.equals("EN_ROUTE")){if(selected==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A vehicle must be assigned");if(selected.equals(previous)){int valid=jdbc.update("UPDATE transport_vehicles SET updated_at=NOW() WHERE id=? AND community_id=? AND status='ASSIGNED'",selected,community);if(valid==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Previously assigned vehicle is no longer assigned");}else{int assigned=jdbc.update("UPDATE transport_vehicles SET status='ASSIGNED',updated_at=NOW() WHERE id=? AND community_id=? AND status='AVAILABLE'",selected,community);if(assigned==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Vehicle is not available in this community");if(previous!=null)jdbc.update("UPDATE transport_vehicles SET status='AVAILABLE',updated_at=NOW() WHERE id=? AND community_id=?",previous,community);}}jdbc.update("UPDATE transport_requests SET status=?,assigned_vehicle_id=?,updated_at=NOW() WHERE id=? AND community_id=?",status,selected,request,community);if((status.equals("COMPLETED")||status.equals("CANCELLED"))&&selected!=null)jdbc.update("UPDATE transport_vehicles SET status='AVAILABLE',updated_at=NOW() WHERE id=? AND community_id=?",selected,community);return jdbc.queryForMap("SELECT id,request_type,priority,status,assigned_vehicle_id,updated_at FROM transport_requests WHERE id=?",request);}
 private void member(UUID user,UUID community){if(!memberships.existsByUserIdAndCommunityIdAndStatus(user,community,ACTIVE))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Active community membership required");}
 private void role(UUID user,UUID community,String required){if(!memberships.existsByUserIdAndCommunityIdAndStatus(user,community,ACTIVE)||(!memberships.existsByUserIdAndCommunityIdAndRoleAndStatus(user,community,required,ACTIVE)&&!memberships.existsByUserIdAndCommunityIdAndRoleAndStatus(user,community,"COMMUNITY_ADMIN",ACTIVE)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,required+" or community administrator role required");}
}
